argumentList:
$ErrorActionPreference='Stop'
$sourcePath='G:\CODEX\New Manga\verification\P02\p02pre-r1g-capture.ps1'
$tokens=$null
$parseErrors=$null
$ast=[System.Management.Automation.Language.Parser]::ParseFile($sourcePath,[ref]$tokens,[ref]$parseErrors)
$required=@('Test-UnreadUserDataStagingPath','Test-SafeRepositoryRelativePath','Get-LinkTypeEvidence','Get-InventoryAction','Test-ExpectedDetachedBranchResult','Assert-InventoryPolicySelfCheck','Assert-CommandSerializationSelfCheck','Get-GitNulPaths','Get-GitIndexModes','Assert-InventoryParserSelfCheck','Get-BoundedPhaseMap')
$defs=@{}
foreach($node in $ast.FindAll({param($n) $n -is [System.Management.Automation.Language.FunctionDefinitionAst]},$true)){
  if($required -contains $node.Name){if($defs.ContainsKey($node.Name)){throw "Duplicate selected function: $($node.Name)"};$defs[$node.Name]=$node}
}
if($parseErrors.Count -ne 0){throw "Parser reported $($parseErrors.Count) errors"}
if($defs.Count -ne $required.Count){throw "Selected function count mismatch: expected=$($required.Count); actual=$($defs.Count)"}
foreach($name in $required){Invoke-Expression $defs[$name].Extent.Text}
Assert-InventoryPolicySelfCheck
Assert-CommandSerializationSelfCheck
Assert-InventoryParserSelfCheck
$expectedKeys=@('identity','mainRepository','scratchRepository','environment','paths','wer','protectedHashes','aclStability')
$phaseInput=[ordered]@{identity='COMPLETED';paths='FAILED';extra='MUST_NOT_ESCAPE'}
$phaseMap=Get-BoundedPhaseMap $phaseInput
if(($phaseMap.Keys -join '|') -ne ($expectedKeys -join '|')){throw 'Bounded phase map key set/order mismatch'}
if($phaseMap.identity -ne 'COMPLETED' -or $phaseMap.paths -ne 'FAILED'){throw 'Bounded phase map did not preserve present phase values'}
if($phaseMap.extra -or $phaseMap.Count -ne 8){throw 'Bounded phase map exposed an extra field'}
$emptyMap=Get-BoundedPhaseMap ([ordered]@{})
$nullMap=Get-BoundedPhaseMap $null
foreach($key in $expectedKeys){if($emptyMap[$key] -ne 'NOT_REACHED' -or $nullMap[$key] -ne 'NOT_REACHED'){throw "Missing phase default mismatch: $key"}}
$result=[ordered]@{
  status='PASS'
  engine=[ordered]@{version=$PSVersionTable.PSVersion.ToString();edition=$PSVersionTable.PSEdition;psHome=$PSHOME;languageMode=$ExecutionContext.SessionState.LanguageMode.ToString()}
  sourcePath=$sourcePath
  parseErrorCount=$parseErrors.Count
  selectedFunctions=$required
  assertions=[ordered]@{
    inventoryPolicy='PASS'
    commandSerialization='PASS'
    inventoryParser='PASS'
    boundedPhaseMapAllEightKeys='PASS'
    boundedPhaseMapMissingAndNullDefault='PASS'
    boundedPhaseMapExtraFieldExcluded='PASS'
  }
  captureScriptInvoked=$false
  hostGetterInvoked=$false
  registryAclProfileApiInvoked=$false
  buildCargoAcInvoked=$false
}
[Console]::Out.WriteLine((ConvertTo-Json -InputObject $result -Depth 8 -Compress))
exit 0
